#include <bits/stdc++.h>
using namespace std;

using i64 = long long;
using i128 = __int128_t;
using f80 = long double;
using u64 = unsigned long long;

const int dx[4] = {1, -1, 0, 0};
const int dy[4] = {0, 0, 1, -1};

int n, maxTime, startX, startY;
string labMap[20], sciMap[20];
int memo[12][12][12][12][62];
int cap[250][250], parent[250];
int dist[20][20], visited[20][20];

bool inRange(int x, int y) {
    return x >= 0 && x < n && y >= 0 && y < n && labMap[x][y] != 'Y' && labMap[x][y] != 'Z';
}

void computeDist() {
    memset(dist, 0x3f, sizeof(dist));
    memset(visited, 0, sizeof(visited));
    dist[startX][startY] = 0;
    visited[startX][startY] = 1;
    queue<int> qx, qy;
    qx.push(startX); qy.push(startY);
    while (!qx.empty()) {
        int x = qx.front(); qx.pop();
        int y = qy.front(); qy.pop();
        for (int k = 0; k < 4; ++k) {
            int nx = x + dx[k];
            int ny = y + dy[k];
            if (inRange(nx, ny) && !visited[nx][ny]) {
                dist[nx][ny] = dist[x][y] + 1;
                visited[nx][ny] = 1;
                qx.push(nx); qy.push(ny);
            }
        }
    }
}

bool checkPath(int x0, int y0, int x1, int y1, int step) {
    if (step > maxTime) return false;
    int& val = memo[x0][y0][x1][y1][step];
    if (val != -1) return val;
    if (x0 == x1 && y0 == y1) return val = (dist[x0][y0] >= step);
    if (dist[x0][y0] <= step) return val = false;
    for (int k = 0; k < 4; ++k) {
        int nx = x0 + dx[k];
        int ny = y0 + dy[k];
        if (inRange(nx, ny) && checkPath(nx, ny, x1, y1, step + 1)) return val = true;
    }
    return val = false;
}

bool bfs(int src, int dst) {
    memset(parent, -1, sizeof(parent));
    parent[src] = -2;
    queue<int> q;
    q.push(src);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int v = src; v <= dst; ++v) {
            if (parent[v] == -1 && cap[u][v] > 0) {
                parent[v] = u;
                q.push(v);
            }
        }
    }
    return parent[dst] != -1;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cout << fixed << setprecision(32);

    cin >> n >> maxTime;
    for (int i = 0; i < n; ++i) cin >> sciMap[i];
    for (int i = 0; i < n; ++i) cin >> labMap[i];

    vector<pair<int, int>> coords;
    vector<int> labCap, sciCap;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (sciMap[i][j] == 'Z') {
                startX = i; startY = j;
            } else if (isdigit(sciMap[i][j])) {
                coords.emplace_back(i, j);
                labCap.push_back(labMap[i][j] - '0');
                sciCap.push_back(sciMap[i][j] - '0');
            }
        }
    }

    int m = coords.size();
    memset(cap, 0, sizeof(cap));
    for (int i = 0; i < m; ++i) {
        cap[0][i + 1] = sciCap[i];
        cap[m + 1 + i][2 * m + 1] = labCap[i];
    }

    computeDist();
    memset(memo, -1, sizeof(memo));
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < m; ++j) {
            if (checkPath(coords[i].first, coords[i].second, coords[j].first, coords[j].second, 0)) {
                cap[i + 1][m + 1 + j] = 1000;
            }
        }
    }

    int maxFlow = 0;
    while (bfs(0, 2 * m + 1)) {
        int sink = 2 * m + 1;
        int flow = 1000000;
        while (parent[sink] >= 0) {
            flow = min(flow, cap[parent[sink]][sink]);
            sink = parent[sink];
        }
        sink = 2 * m + 1;
        while (parent[sink] >= 0) {
            cap[parent[sink]][sink] -= flow;
            cap[sink][parent[sink]] += flow;
            sink = parent[sink];
        }
        maxFlow += flow;
    }

    cout << maxFlow;
    return 0;
}
